      if (info?.current && !hasUpdate(info)) return { text: `console-status ${versionLine(info)}，不需要更新。` }
      return { text: await runUpdate($) }
    }
    if (arg === 'plain') {
      const plain = await update($, isPlain, v => !v)
      return { text: plain ? '表格改用純文字列（/console plain 切回互動列）。' : '表格改用互動列。' }
