      await $.ui.close({ id: PANE }).catch(() => {})
      await update($, isPaneOpen, () => false)
      return { text: '面板已關閉。' }
    }
    await $.ui.open({ id: PANE, title: '主控台總覽' })
    await update($, isPaneOpen, () => true)
    return { text: '面板已開啟。' }
